import { AlchemystAI } from '@alchemystai/sdk';
import * as fs from 'fs';
import * as path from 'path';

async function main() {
  const apiKey = process.env.ALCHEMYST_AI_API_KEY;
  if (!apiKey) {
    console.error("ALCHEMYST_AI_API_KEY is not set");
    process.exit(1);
  }

  const runId = fs.readFileSync('/logs/artifacts/run-id', 'utf8').trim();
  console.log(`Run ID: ${runId}`);

  const client = new AlchemystAI({ apiKey });

  const fileName = `test_doc_${runId}`;
  console.log(`Seeding document: ${fileName}`);

  try {
    const addRes = await client.v1.context.add({
      context_type: 'resource',
      source: 'docs',
      scope: 'internal',
      documents: [
        {
          content: "This is a test support document for troubleshooting.",
          metadata: {
            file_name: fileName,
            group_name: ["support"]
          }
        } as any
      ]
    });
    console.log("Add response:", JSON.stringify(addRes, null, 2));
  } catch (err: any) {
    console.error("Add failed:", err);
  }

  console.log("\nSearching with metadata: { groupName: ['support'] }");
  try {
    const searchRes = await client.v1.context.search({
      query: "test support document",
      scope: 'internal',
      minimum_similarity_threshold: 0.1,
      similarity_threshold: 0.1,
      metadata: { groupName: ["support"] } as any
    });
    console.log("Search response:", JSON.stringify(searchRes, null, 2));
  } catch (err: any) {
    console.error("Search failed:", err);
  }
}

main().catch(console.error);

